<?php
/** Plugin Name: TEMP PS S1717v — kategoriju (hub) ir gamintoju aprasymu ikelimas. Fazes: 1 sausas, 2 vykdyti (term description, bak opcija ps_s1718_tekstai_bak), 3 patikra, 9 atstatyti. Sudaromas per build_v.py is tekstai/*.py */
add_action('wp_loaded', function(){
  if(!isset($_GET['ps_s1718v'])) return;
  $f=$_GET['ps_s1718v']; @set_time_limit(170); global $wpdb; $r=['v'=>'S1718v','faze'=>$f]; $BAK='ps_s1718_tekstai_bak';
  $T=json_decode(base64_decode(''),true); // [ ['tax'=>'product_cat','slug'=>..,'id'=>..,'html'=>..], ... ]
  $cut=function($v,$n=160){ $v=(string)$v; return mb_strlen($v)>$n?mb_substr($v,0,$n).'…':$v; };
  try{
  if(!is_array($T)){ $r['klaida']='tekstai neiskoduoti'; wp_send_json($r); }
  if($f==='1'){ foreach($T as $x){ $t=isset($x['id'])?get_term((int)$x['id'],$x['tax']):get_term_by('slug',$x['slug'],$x['tax']); $r['planas'][]=[$x['tax'],$x['slug'],$t?$t->term_id:null,$t?mb_strlen($t->description):'NERA',mb_strlen($x['html']),$cut(wp_strip_all_tags($x['html']),90)]; } $r['bak_yra']=(bool)get_option($BAK); }
  if($f==='2'){
    if(get_option($BAK)){ $r['klaida']='bak jau yra'; wp_send_json($r); }
    $bak=['laikas'=>current_time('mysql'),'terminai'=>[]]; $rez=[];
    foreach($T as $x){ $t=isset($x['id'])?get_term((int)$x['id'],$x['tax']):get_term_by('slug',$x['slug'],$x['tax']); if(!$t){ $rez[]=[$x['slug'],'NERA']; continue; } $bak['terminai'][]=['tax'=>$x['tax'],'id'=>$t->term_id,'description'=>$t->description,'mt'=>get_term_meta($t->term_id,'rank_math_title',true),'md'=>get_term_meta($t->term_id,'rank_math_description',true)]; }
    update_option($BAK,$bak,false);
    foreach($T as $x){ $t=isset($x['id'])?get_term((int)$x['id'],$x['tax']):get_term_by('slug',$x['slug'],$x['tax']); if(!$t) continue; $u=wp_update_term($t->term_id,$x['tax'],['description'=>wp_kses_post($x['html'])]); $m=''; if(!empty($x['mt'])){ update_term_meta($t->term_id,'rank_math_title',$x['mt']); $m.='+mt'; } if(!empty($x['md'])){ update_term_meta($t->term_id,'rank_math_description',$x['md']); $m.='+md'; } $rez[]=[$x['slug'],(is_wp_error($u)?'KLAIDA '.$u->get_error_message():'ok').$m]; }
    foreach($wpdb->get_col("SELECT option_name FROM {$wpdb->options} WHERE option_name LIKE '_transient_ps_seo_sabl_%'") as $on) delete_option($on);
    $r['rez']=$rez; if(function_exists('wp_cache_clear_cache')) wp_cache_clear_cache();
  }
  if($f==='3'){ foreach($T as $x){ $t=isset($x['id'])?get_term((int)$x['id'],$x['tax']):get_term_by('slug',$x['slug'],$x['tax']); if(!$t) continue; $res=wp_remote_get(get_term_link($t).'?ps_v=1',['timeout'=>25]); $h=wp_remote_retrieve_body($res); $r['patikra'][$x['slug']]=['code'=>wp_remote_retrieve_response_code($res),'desc_len'=>mb_strlen($t->description),'term_desc_html'=>strpos($h,'term-description')!==false,'meta'=>$cut(html_entity_decode(preg_match('#<meta name="description" content="([^"]*)"#i',$h,$m)?$m[1]:''),120)]; } }
  if($f==='9'){ $bak=get_option($BAK); if(!$bak){ $r['klaida']='bak nera'; wp_send_json($r); } foreach($bak['terminai'] as $b){ wp_update_term($b['id'],$b['tax'],['description'=>$b['description']]); if(array_key_exists('mt',$b)){ if(''===(string)$b['mt']) delete_term_meta($b['id'],'rank_math_title'); else update_term_meta($b['id'],'rank_math_title',$b['mt']); } if(array_key_exists('md',$b)){ if(''===(string)$b['md']) delete_term_meta($b['id'],'rank_math_description'); else update_term_meta($b['id'],'rank_math_description',$b['md']); } } delete_option($BAK); if(function_exists('wp_cache_clear_cache')) wp_cache_clear_cache(); $r['atstatyta']=count($bak['terminai']); }
  }catch(Throwable $e){ $r['FATAL']=$e->getMessage().' @'.$e->getLine(); }
  wp_send_json($r);
}, 1);
